-- Stores the frozen A6Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a6q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A6Q';
 v_cp constant text := 'A6Q_C2';
 v_wi constant bigint := 1116;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A6Q_C2';
 v_packet_sha constant text := '2d68fab4117d1617c1ffd32129c31a24c0ee75f4b23f3cad9861ff0cf6aa2c94';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"dimensions":["functional","data","permissions","state","errors","side_effects"],"forbidden_solution_patterns":["\\bredis\\b","\\bkafka\\b","\\bpostgres\\w*","\\breact\\b","\\bsql\\b","\\bapi\\b","\\bendpoint\\b","\\btrigger\\b","\\bmigraci\\w+","\\bmicroservic\\w+","\\brpc\\b","\\bedge function\\b","\\btabla\\b","\\bbase de datos\\b","\\bcomponente\\b"],"min_decisions_covered":4,"must_be_blocked":["permissions","state","errors","side_effects"],"req_keys":["depends_on_decisions","requirement_id","source_ref","statement","status","type"],"req_types":["FUNCTIONAL","DATA","NON_FUNCTIONAL"],"request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001"},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a5_stage_output\": {\n    \"current_decisions\": [],\n    \"current_decisions_basis\": \"La entrada A4 no contiene decisiones vigentes respaldadas por autoridad funcional. Sus referencias documentan el paquete de solicitud, el evento de traspaso y brechas no resueltas. No se puede considerar aprobada ninguna regla de producto a partir de estas fuentes.\",\n    \"decision_statement\": \"Se identifican cinco decisiones funcionales materiales pendientes sobre alcance del piloto, definición del ahorro, momento de comunicación, distinción respecto de la cuota y criterios de aceptación. Todas permanecen reservadas al propietario humano y ninguna ha sido aprobada por el agente. Antes de solicitar decisiones nuevas, corresponde contrastarlas con las reglas y decisiones vigentes, cuya autoridad no fue suministrada. La ausencia de fuentes no invalida decisiones existentes ni demuestra que todas requieran una nueva aprobación humana. La identificación de la implementación existente, la reconstrucción de la línea base AS-IS y la verificación de autoridad son actividades de investigación y no decisiones que deban trasladarse automáticamente al propietario. No se ha seleccionado ninguna alternativa funcional ni técnica, resuelto ningún ADR o autorizado implementación alguna.\",\n    \"decisions_approved_by_agent\": [],\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_IDENTITY_UNRESOLVED\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:IMPLEMENTATION_STATE_UNVERIFIED\",\n      \"gap:AS_IS_BASELINE_MISSING\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"impact:A4-DIRECT-001\",\n      \"impact:A4-DIRECT-002\",\n      \"impact:A4-DEPENDENCY-003\",\n      \"impact:A4-INDIRECT-001\",\n      \"impact:A4-INDIRECT-002\"\n    ],\n    \"no_self_approval\": true,\n    \"pending_decisions\": [\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-001\",\n        \"gap_ref\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"impact_ref\": \"A4-DIRECT-001\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué capacidad funcional, canales y segmentos de clientes deben quedar incluidos en el alcance del piloto para comunicar el ahorro antes de aceptar una oferta?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-002\",\n        \"gap_ref\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"impact_ref\": \"A4-DIRECT-002\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué definición de ahorro y qué base de comparación deben utilizarse para comunicar al cliente el beneficio económico de negociar su deuda?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-003\",\n        \"gap_ref\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"impact_ref\": \"A4-DEPENDENCY-003\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿En qué estado de la oferta y bajo qué condiciones debe estar disponible la información del ahorro antes de que el cliente acepte?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-004\",\n        \"gap_ref\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n        \"impact_ref\": \"A4-INDIRECT-001\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué distinción funcional debe establecerse entre el ahorro de la negociación y el monto de la cuota para evitar que el cliente confunda ambos conceptos?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-005\",\n        \"gap_ref\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n        \"impact_ref\": \"A4-INDIRECT-002\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué criterios de aceptación deben utilizarse para determinar que los clientes comprenden el ahorro y no lo confunden con la cuota durante el piloto?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      }\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A5_DECISIONS_OUTPUT_V1\"\n  }\n}","input_origin":"A5Q_C2 GPT Native RAW (raw_output_sha256 8db2b41750ab425b85a5d1c6bbe336ee4ff75052c40e46c5101b9564936a09f1)","input_sha256":"960f333438d0799d95d237f91587302e7b8e973130a2ff65d0144a7eabbc6c7f","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","requirements","dimensions","evidence_refs","no_unlicensed_how","requirements_statement"],"schema":"A6_REQUIREMENTS_OUTPUT_V1","validator":"analysis_qualification_a6q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"2d68fab4117d1617c1ffd32129c31a24c0ee75f4b23f3cad9861ff0cf6aa2c94","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A6 (requisitos tipados) del perfil de análisis. Recibes la salida de la etapa A5 (abajo). Expresa QUÉ debe cumplir el cambio, sin indicar CÓMO implementarlo (nada de tecnología, almacenamiento, interfaces técnicas ni diseño). Toda decisión de A5 sigue pendiente, así que ningún requisito puede darse por confirmado: cada requisito es provisional y depende de decisiones pendientes. No inventes permisos, estados, errores, efectos colaterales ni cifras: si la entrada no los respalda, declara esa dimensión como bloqueada. Referencias válidas: las evidence_refs de la entrada y 'decision:<decision_id>' para cada decisión pendiente. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, requirements, dimensions, evidence_refs, no_unlicensed_how, requirements_statement. schema_version='A6_REQUIREMENTS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. requirements: lista de {requirement_id (único), type (FUNCTIONAL|DATA|NON_FUNCTIONAL), statement (qué se exige, texto, sin cifras que no estén en la entrada), status='PROVISIONAL_PENDING_DECISION', depends_on_decisions (lista no vacía de decision_id de la entrada), source_ref (una referencia válida)}; deben depender en conjunto de al menos 4 decisiones distintas y al menos uno debe ser FUNCTIONAL. dimensions: objeto con exactamente las claves functional, data, permissions, state, errors, side_effects; cada una es {status ('PROVISIONAL_PENDING_DECISION' o 'BLOCKED_UNDETERMINED'), blocked_by (lista de decision_id de la entrada), note (texto)}. permissions, state, errors y side_effects deben ser 'BLOCKED_UNDETERMINED' con blocked_by no vacío. evidence_refs: lista no vacía de referencias válidas. no_unlicensed_how=true. requirements_statement: texto que explica qué quedó especificado y qué sigue bloqueado.\n\nENTRADA (JSON):\n{\n  \"a5_stage_output\": {\n    \"current_decisions\": [],\n    \"current_decisions_basis\": \"La entrada A4 no contiene decisiones vigentes respaldadas por autoridad funcional. Sus referencias documentan el paquete de solicitud, el evento de traspaso y brechas no resueltas. No se puede considerar aprobada ninguna regla de producto a partir de estas fuentes.\",\n    \"decision_statement\": \"Se identifican cinco decisiones funcionales materiales pendientes sobre alcance del piloto, definición del ahorro, momento de comunicación, distinción respecto de la cuota y criterios de aceptación. Todas permanecen reservadas al propietario humano y ninguna ha sido aprobada por el agente. Antes de solicitar decisiones nuevas, corresponde contrastarlas con las reglas y decisiones vigentes, cuya autoridad no fue suministrada. La ausencia de fuentes no invalida decisiones existentes ni demuestra que todas requieran una nueva aprobación humana. La identificación de la implementación existente, la reconstrucción de la línea base AS-IS y la verificación de autoridad son actividades de investigación y no decisiones que deban trasladarse automáticamente al propietario. No se ha seleccionado ninguna alternativa funcional ni técnica, resuelto ningún ADR o autorizado implementación alguna.\",\n    \"decisions_approved_by_agent\": [],\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_IDENTITY_UNRESOLVED\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:IMPLEMENTATION_STATE_UNVERIFIED\",\n      \"gap:AS_IS_BASELINE_MISSING\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"impact:A4-DIRECT-001\",\n      \"impact:A4-DIRECT-002\",\n      \"impact:A4-DEPENDENCY-003\",\n      \"impact:A4-INDIRECT-001\",\n      \"impact:A4-INDIRECT-002\"\n    ],\n    \"no_self_approval\": true,\n    \"pending_decisions\": [\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-001\",\n        \"gap_ref\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"impact_ref\": \"A4-DIRECT-001\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué capacidad funcional, canales y segmentos de clientes deben quedar incluidos en el alcance del piloto para comunicar el ahorro antes de aceptar una oferta?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-002\",\n        \"gap_ref\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"impact_ref\": \"A4-DIRECT-002\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué definición de ahorro y qué base de comparación deben utilizarse para comunicar al cliente el beneficio económico de negociar su deuda?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-003\",\n        \"gap_ref\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"impact_ref\": \"A4-DEPENDENCY-003\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿En qué estado de la oferta y bajo qué condiciones debe estar disponible la información del ahorro antes de que el cliente acepte?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-004\",\n        \"gap_ref\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n        \"impact_ref\": \"A4-INDIRECT-001\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué distinción funcional debe establecerse entre el ahorro de la negociación y el monto de la cuota para evitar que el cliente confunda ambos conceptos?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-005\",\n        \"gap_ref\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n        \"impact_ref\": \"A4-INDIRECT-002\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué criterios de aceptación deben utilizarse para determinar que los clientes comprenden el ahorro y no lo confunden con la cuota durante el piloto?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      }\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A5_DECISIONS_OUTPUT_V1\"\n  }\n}","request_sha256":"e5c9a82cee795e15f46bd1d68d8ee605ed52ad4242f6e491de73cd740759aa15","run_id":"A6Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A6","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A6Q/A6Q_C2","unit":"A6"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A6Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A6Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A6Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A6Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A6Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A6Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A6Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A6Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A6Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A6Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A6Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A6Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A6Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A6Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A6Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A6Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A6Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a6q_c2_prep$;
COMMIT;
